The measure $d(\cdot,\cdot)$ is said to be accumulating error cost (AEC) measure if it satisfies:
\begin{equation}
d(\mathbf{x}_{1:t},\mathbf{y}_{1:t}) \leq d(\mathbf{x}_{1:t'},\mathbf{y}_{1:t'})
\end{equation}
for all $\mathbf{x} \in \mathcal{X}^{n}$, $\mathbf{y} \in \mathcal{Y}^{n}$ and $t < t'$.

\label{DcleDcfeachievability}
If the SSDGU algorithm with an AEC measure $d(\cdot,\cdot)$ and a computational limit paramater $L$ is used to decode an independent random message $\mathbf{m}$ that is uniformly selected from $\lbrace 0,1\rbrace^{k}$ from the output $\mathbf{y}$ of noisy channel that takes the coded bits $\mathbf{x}=\mathbf{G}\mathbf{m}$ with  $\mathbf{G}$ being the generator matrix  of a $(n,k)$-random tree code with the tree structure $s(t)$, then the probability of error for the decoded message $\mathbf{\hat{m}}$ satisfies:
\begin{equation}
\label{theboundforerrorDcleDcfe}
\Pr(\mathbf{\hat{m}}\neq \mathbf{m}) \leq D_{\text{CLE}}[s,d]+D_{\text{CFE}}[s,d],
\end{equation}
where $D_{\text{CLE}}[s,d]$ is the computation-limit-error (CLE) bound which is expressed as
\begin{eqnarray}
&&D_{\text{CLE}}[s,d] = \nonumber\\ 
&&\Pr\left( c_{0}+\displaystyle\sum_{h=1}^{h_{f}-1}c_{h}\displaystyle\sum_{\mathbf{m'}_{1:s(b_{h})}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace} \geq L\right) \nonumber
\end{eqnarray}  
, where the second summation runs over all $\mathbf{m'}_{1:s(b_{h})} \in \lbrace 0,1\rbrace^{s(b_{h})}$ and  $c_{h}=2^{s(b_{h+1})-s(b_{h})}$, $c_{0}=2^{s(b_{1})}$, and $D_{\text{CFE}}[s,d]$ is the computation-free-error (CFE) bound which is defined as
\begin{eqnarray}
&&D_{\text{CFE}}[s,d] = \nonumber\\
&&\Pr\left( \displaystyle\sum_{\mathbf{m'}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace} \geq 2\right),
\end{eqnarray}
where the summation runs over all $\mathbf{m'} \in \lbrace 0, 1\rbrace^{k}$.

The probability of error that $\mathbf{\hat{m}}\neq \mathbf{m}$ can be decomposed into two terms as follows:
\begin{equation}
\label{errordecompose}
\Pr(\mathbf{\hat{m}}\neq \mathbf{m}) = \Pr(\mathbf{\hat{m}}=\varepsilon)+\Pr(\mathbf{\hat{m}}\neq \mathbf{m},\mathbf{\hat{m}} \neq  \varepsilon). 
\end{equation} 
Now, we will give individual upper bound for the RHS terms in \eqref{errordecompose}.

First, observe that any node at branching time $h+1$ is not checked if its parent node $\mathbf{m'}_{1:s(b_{h})}$ satisfies $d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})})> d_{\mid \mathbf{y}}(\mathbf{m})$. The reason is that the stack of the decoding algorithm always contains an ancestor of $\mathbf{m}$ which has a decoding error cost at most as $d_{\mid \mathbf{y}}(\mathbf{m})$ (due to the definition of AEC measures) hence a node with a  decoding error cost lower than of $m'_{1:s(b_{h})}$ always exists. Therefore, the number of nodes that the decoding algorithm checks $N_{c}$ satisfies:
\begin{equation}
\label{upperboundforNc}
N_{c}\leq c_{0}+\displaystyle\sum_{h=1}^{h_{f}-1}c_{h}\displaystyle\sum_{\mathbf{m'}_{1:s(b_{h})}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}, 
\end{equation}
with probability $1$. Accordingly, we have:
\begin{equation}
\label{Dclebound}
\Pr(\mathbf{\hat{m}}=\varepsilon) \leq D_{\text{CLE}}[s,d].
\end{equation}
Secondly, observe that if $\mathbf{\hat{m}} \neq \varepsilon$, a wrong message is decoded only if there exists at least two terminal nodes $\mathbf{m'}$ that satisfy $d_{\mid \mathbf{y}}(\mathbf{m'}) \leq d_{\mid \mathbf{y}}(\mathbf{m})$ as $\mathbf{m'}=\mathbf{m}$ always satisfies the condition. Accordingly, we have:
\begin{equation}
\label{Dcfebound}
\Pr(\mathbf{\hat{m}}\neq \mathbf{m},\mathbf{\hat{m}} \neq  \varepsilon) \leq D_{\text{CFE}}[s,d].
\end{equation}
Combining \eqref{errordecompose} with \eqref{Dclebound} and \eqref{Dcfebound} proves \eqref{theboundforerrorDcleDcfe}.

The functional $D_{\text{E}}^{\text{(U)}}[s,d]$ is a uniform upper bound for $D_{\text{E}}[s,d]$ in $\mathcal{A}_{d,\text{AEC}}\times \mathcal{A}_{s}(n,k)$, i.e.,
\begin{equation}
\label{DEUbound}
D_{\text{E}}[s,d] \leq D_{\text{E}}^{\text{(U)}}[s,d],
\end{equation} 
for all $s \in \mathcal{A}_{s}(n,k)$ and $d \in \mathcal{A}_{d,\text{AEC}}$.

First observe that:
\begin{eqnarray}
\label{mbarforCLE}
&&\displaystyle\sum_{\mathbf{m'}_{1:s(b_{h})}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}\nonumber\\
&& =2^{s(b_{h})}\mathbb{E}_{\mathbf{\bar{m}}}\left[ \mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{\bar{m}}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}\right], \text{w.p.1} 
\end{eqnarray}
where the expectation is taken over only on $\mathbf{\bar{m}}_{1:s(b_{h})}$.
Then, consider:
\begin{eqnarray}
\label{DCLEUbound}
&&D_{\text{CLE}}[s,d] \nonumber\\ 
&&=\Pr\left( c_{0}+\displaystyle\sum_{h=1}^{h_{f}-1}c_{h}\displaystyle\sum_{\mathbf{m'}_{1:s(b_{h})}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace} \geq L\right) \nonumber\\ 
&&=\Pr\left( \frac{c_{0}}{L}+\displaystyle\sum_{h=1}^{h_{f}-1}\frac{c_{h}}{L}\displaystyle\sum_{\mathbf{m'}_{1:s(b_{h})}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace} \geq 1\right) \nonumber\\
&&\leq\mathbb{E} \left[ \left[  \frac{c_{0}}{L}+\displaystyle\sum_{h=1}^{h_{f}-1}\frac{c_{h}}{L}\displaystyle\sum_{\mathbf{m'}_{1:s(b_{h})}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}\right]_{\leq 1}\right]  \nonumber\\
&&=\mathbb{E} \left[ \left[ \displaystyle\sum_{h=0}^{h_{f}-1}\frac{c_{h}2^{s(b_{h})}}{L}\mathbb{E}_{\mathbf{\bar{m}}}\left[ \mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{\bar{m}}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}\right]\right]_{\leq 1}\right]  \nonumber\\
&&=\mathbb{E} \left[ \left[ \displaystyle\sum_{h=0}^{h_{f}-1}\frac{2^{s(b_{h+1})}}{L}\mathbb{E}_{\mathbf{\bar{m}}}\left[ \mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{\bar{m}}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}\right]\right]_{\leq 1}\right]  \nonumber\\
&&\leq\mathbb{E} \left[ \left[ \displaystyle\sum_{h=0}^{h_{f}-1}v_{h}\Pr\left(d_{\mid \mathbf{y}}(\mathbf{\bar{m}}_{1:s(b_{h})}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\mid \mathbf{x}, \mathbf{y}\right) \right]_{\leq 1}\right]\nonumber\\
&&=D_{\text{CLE}}^{\text{(U)}}[s,d],  
\end{eqnarray}
where the first inequality is due to that $\Pr(X \geq 1)\leq \mathbb{E}[[X]_{\leq 1}]$ for a non-negative random variable $X$, the third equality is due to \eqref{mbarforCLE}, the fourth equality is due to $c_{h}=2^{s(b_{h+1})-s(b_{h})}$, and the second inequality is due to Jensen's inequality for the commutation of $[\cdot]_{\leq 1}$ and $\mathbb{E}[\cdot \mid \mathbf{x}, \mathbf{y}, \mathbf{\bar{m}}]$ operations. 

Similar to \eqref{mbarforCLE}, observe that:
\begin{eqnarray}
\label{mbarforCFE}
\displaystyle\sum_{\mathbf{m'}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}=2^{k}\mathbb{E}_{\mathbf{\bar{m}}}\left[ \mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{\bar{m}}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}\right], \text{w.p.1} \nonumber\\
\end{eqnarray}
where the expectation is taken over only on  $\mathbf{\bar{m}}$.
Then, consider:
\begin{eqnarray}
\label{DCFEUbound}
&&D_{\text{CFE}}[s,d] \nonumber\\
&&=\Pr\left( \displaystyle\sum_{\mathbf{m'}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace} \geq 2\right)\nonumber\\
&&=\Pr\left( \displaystyle\sum_{\mathbf{m'}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}-1 \geq 1\right)\nonumber\\
&&=\mathbb{E}\left[ \left[ \displaystyle\sum_{\mathbf{m'}}\mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{m'}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\rbrace}-1\right]_{\leq 1}\right] \nonumber\\
&&=\mathbb{E}\left[ \left[ 2^{k}\mathbb{E}_{\mathbf{\bar{m}}}\left[ \mathbb{I}_{\lbrace d_{\mid \mathbf{y}}(\mathbf{\bar{m}}) \leq d_{\mid \mathbf{y}}(\mathbf{m})}\right]-1\right]_{\leq 1}\right] \nonumber\\
&&\leq\mathbb{E}\left[ \left[ 2^{k}\Pr\left( d_{\mid \mathbf{y}}(\mathbf{\bar{m}}) \leq d_{\mid \mathbf{y}}(\mathbf{m})\mid \mathbf{x}, \mathbf{y}\right) -1\right]_{\leq 1}\right] \nonumber\\
&&=D_{\text{CFE}}^{(U)}[s,d],
\end{eqnarray}
where the third equality is due to that $\Pr(X \geq 1)=\mathbb{E}[[X]_{\leq 1}]$ for $X \in \lbrace 0, 1, \cdots, 2^{k}\rbrace$, the fourth equality is due to \eqref{mbarforCFE}, and the inequality is due to Jensen's inequality for the commutation of $[\cdot]_{\leq 1}$ and $\mathbb{E}[\cdot \mid \mathbf{x}, \mathbf{y}, \mathbf{\bar{m}}]$ operations.

Combining \eqref{DCLEUbound} and \eqref{DCFEUbound} proves \eqref{DEUbound}.

\label{expectedNcboundDCLEML}
If $N_{c}$ is the number of nodes that the decoding algorithm checks for a random run of the SSDGU algorithm, then
\begin{equation}
\label{upperboundforexpectedNc}
\mathbb{E}[N_{c}] \leq  D_{\text{CLE}}^{\text{(M)}}[s,d]L,
\end{equation}  
for all $s \in \mathcal{A}_{s}(n,k)$ and $d \in \mathcal{A}_{d,\text{AEC}}$.

\label{RCUconnectionforDCFEU}
If $\mathcal{Y}$ is discrete, $s(1)=k$ and
\begin{equation}
\label{loglikelihoodford}
d(\mathbf{x'}_{1:t},\mathbf{y'}_{1:t})= -\log_{2}\left( P_{\mathbf{y}_{1:t} \mid \mathbf{x}_{1:t}}\left( \mathbf{y'}_{1:t} \mid \mathbf{x'}_{1:t}\right) \right), 
\end{equation}
then
\begin{equation}
\label{RCUcaseforDCFEU}
D_{\text{CFE}}^{\text{(U)}}[s,d] = \mathbb{E}\left[ \left[ \left( 2^{k}-1\right)\Pr\left( i(\mathbf{\bar{x}},\mathbf{y}) \geq i(\mathbf{x},\mathbf{y})\mid \mathbf{x}, \mathbf{y}\right)\right]_{\leq 1}\right],
\end{equation}
where $i(\mathbf{x'},\mathbf{y'})=\log_{2}\left( \frac{P_{\mathbf{y} \mid \mathbf{x}}\left( \mathbf{y'} \mid \mathbf{x'}\right) }{P_{\mathbf{y}}\left( \mathbf{y'}\right) }\right)$ is the information density and $\mathbf{\bar{x}}$ is uniformly selected from $\lbrace 0,1\rbrace^{n}$ being independent from other random variables.

A channel $P_{\mathbf{y} \mid \mathbf{x}}$ is said to be causal if it satisfies:
\begin{equation}
P_{\mathbf{y}_{1:t} \mid \mathbf{x}_{1:t}}(\mathbf{y'}_{1:t} \mid \mathbf{x'}_{1:t})=\displaystyle\prod_{t'=1}^{t}P_{\mathbf{y}_{t'} \mid \mathbf{x}_{1:t'}}(\mathbf{y'}_{t'} \mid \mathbf{x'}_{1:t'}),
\end{equation}
for all $t \in \lbrace 1,\cdots, n\rbrace$.

If $P_{\mathbf{y} \mid \mathbf{x}}$ is a memoryless channel, then the functional $D_{\text{E}}^{\text{(C)}}[s,d]$ is a uniform upper bound for $D_{\text{E}}^{\text{(U)}}[s,d]$ in $\mathcal{A}_{d,\text{AEC}}\times \mathcal{A}_{s}(n,k)$, i.e.,
\begin{equation}
\label{DECbound}
D_{\text{E}}[s,d]^{\text{(U)}} \leq D_{\text{E}}^{\text{(C)}}[s,d],
\end{equation} 
for all $s \in \mathcal{A}_{s}(n,k)$ and $d \in \mathcal{A}_{d,\text{AEC}}$,
where
\begin{equation}
D_{\text{E}}^{\text{(C)}}[s,d]= D_{\text{CLE}}^{\text{(C)}}[s,d]+D_{\text{CFE}}^{\text{(C)}}[s,d],
\end{equation}
where
\begin{eqnarray}
&&D_{\text{CLE}}^{\text{(C)}}[s,d] = \nonumber\\
&&\displaystyle\sum_{h=0}^{h_{f}-1}\displaystyle\sum_{h'=0}^{h} v_{h;h'} \mathbb{E}\left[ 2^{\vartheta_{h;h'}\left[ d_{b_{h'+1}:n}(\mathbf{x},\mathbf{y})-d_{b_{h'+1}:r_{[h]}}(\mathbf{\bar{x}},\mathbf{y})\right]  }\right]^{\varrho_{h;h'}},\nonumber\\
\end{eqnarray}
for $\vartheta_{h;h'} \geq 0$ and $\varrho_{h;h'}\in [0,1]$, and
\begin{eqnarray}
&&D_{\text{CFE}}^{\text{(C)}}[s,d] = \nonumber\\
&&\mathbb{E}\left[ \displaystyle\sum_{h=0}^{h_{f}-1}w_{h}^{\rho_{h}}\mathbb{E}\left[  2^{\theta_{h}\left[ d_{t_{h} :n}(\mathbf{x},\mathbf{y})-d_{t_{h}: n}(\mathbf{\bar{x}},\mathbf{y}) \right]}\mid \mathbf{y}\right]^{\rho_{h}}\right],\nonumber\\
\end{eqnarray}
for $\theta_{h} \geq 0$ and $\rho_{h} \in [0,1]$.
